// Normalize Sentry / healthchecks / WUD payloads into one shape, then
// build a single Discord message. Source is inferred from the payload, or
// passed explicitly as ?source= on the webhook URL.
const src = ($json.query && $json.query.source) || $json.source || 'unknown';
const b = $json.body || $json;

let title = 'event';
let detail = '';
let emoji = '🔵';

if (src === 'sentry' || b.event) {
  emoji = '🟣';
  const e = b.event || b;
  title = `Sentry: ${e.title || e.metadata?.value || b.message || 'issue'}`;
  detail = `project=${b.project_name || b.project || '?'} level=${e.level || '?'}`;
} else if (src === 'healthchecks' || b.check) {
  const status = (b.check && b.check.status) || b.status || '?';
  emoji = status === 'down' ? '🔴' : '🟢';
  title = `Healthchecks: ${(b.check && b.check.name) || b.name || 'check'} is ${status}`;
  detail = `last_ping=${(b.check && b.check.last_ping) || '?'}`;
} else if (src === 'wud' || b.container) {
  emoji = '🟠';
  title = `WUD: update for ${b.container?.name || b.name || 'container'}`;
  detail = `${b.container?.image?.tag?.value || ''} → ${b.container?.updateKind?.localValue || ''}=>${b.container?.updateKind?.remoteValue || ''}`;
}

const content = `${emoji} **[${src}]** ${title}\n${detail ? '`' + detail + '`' : ''}`;
return [{ json: { content, source: src } }];
